/* Fonts from assets/ (paths relative to app/),
 * compiled into the eboot, so nothing depends on the app's file layout.
 * Generated by scripts/gen_assets.py. */
#include "ui_assets.h"

__asm__(".section .rodata\n.balign 16\n.global nuvio_blob_font_inter_regular\nnuvio_blob_font_inter_regular:\n.incbin \"assets/fonts/Inter-Regular.ttf\"\n.byte 0\n.global nuvio_blob_font_inter_regular_end\nnuvio_blob_font_inter_regular_end:\n.previous\n");
extern const uint8_t nuvio_blob_font_inter_regular[], nuvio_blob_font_inter_regular_end[];
ui_asset ui_asset_font_inter_regular(void)
{
    ui_asset a = {nuvio_blob_font_inter_regular, (size_t)(nuvio_blob_font_inter_regular_end - nuvio_blob_font_inter_regular) - 1};
    return a;
}

